  function events(page,owner){const stories=JSON.parse(localStorage.getItem('nexora-v31:community-stories')||'[]').filter(row=>row.pageId===page.id&&row.expiresAt>Date.now());return card('Page Story',`<div class="po-story-row"><button class="po-story" data-po-page-action="story">${avatar(page.title,'gold')}<span>Page Story</span><small>${stories.length?Math.max(1,Math.ceil((stories[0].expiresAt-Date.now())/3600000))+' hours left':'24 hours'}</small></button>${owner?'<button class="po-story" data-po-page-action="add-story"><span class="po-story-add">+</span><span>Add Story</span></button>':''}</div><p class="po-page-note">Stories appear around the Page avatar and expire after 24 hours.</p>`)+[...(page.poSupplement?.events||[]),...apiData().feed.filter(row=>row.kind==='event'&&row.pageId===page.id)].map((row,index)=>card('',`<div class="po-page-row">${mediaThumb(row.title,index+2)}<div><strong>${esc(row.title)}</strong><p class="po-page-note">${new Date(row.date+'T12:00:00').toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'})} · ${esc(row.time||'')}</p></div></div><div class="po-page-actions">${button(row.interested?.includes(api.member)?'Interested ✓':'Interested','interest',row.id)}${button('Share event','share')}</div>`)).join('')+(owner?button('Create event','event','',true):'');}
