    if(action==='write-review'){show('Write your review',`<form data-po-new-review><label>Rating<select name="rating">${[5,4,3,2,1].map(n=>`<option value="${n}">${'★'.repeat(n)}</option>`).join('')}</select></label><label>Review<textarea name="review" rows="4" required></textarea></label><button class="btn primary" type="submit">Save review</button><p class="po-page-note">Sample data</p></form>`);return;}
