    if(action==='intro-video'){const row=apiData().pagePosts.find(row=>row.id===current.poSupplement?.pinnedVideo)||apiData().pagePosts.find(row=>row.pageId===current.id&&(row.videoId||row.media?.some(item=>item.type==='video'&&item.src)));if(row){show('Introduction video',`<video controls autoplay playsinline ${row.videoId?'data-po-video="'+esc(row.videoId)+'"':'src="'+esc(row.media.find(item=>item.type==='video').src)+'"'}></video>`);window.NEXORA_COMMUNITY_PO.hydrateVideos();}else show('Introduction video','<video controls playsinline autoplay src="/html/v3.1/community/page-videos/nail-colors.mp4"></video>');return;}
    if(action==='remove-follower'||action==='block-follower'){if(current.owner!==api.member)return;persist(()=>{const follower=(current.followerProfiles||current.poSupplement?.followerSamples||[]).find(row=>row.id===value);if(current.followerProfiles)current.followerProfiles=current.followerProfiles.filter(row=>row.id!==value);else {current.poSupplement.followerSamples=(current.poSupplement.followerSamples||[]).filter(row=>row.id!==value);if(follower)current.followers=Math.max(0,Number(current.followers||0)-1);}if(action==='block-follower'){current.blockedFollowers=[...new Set([...(current.blockedFollowers||[]),value,follower?.name].filter(Boolean))];}});open('followers');return;}if(action==='reply'){const row=current.poSupplement.reviews.find(row=>row.id===value);show('Reply to '+row.name,`<form data-po-review="${value}"><label>Reply<textarea name="reply" rows="4" required>${esc(row.reply||'')}</textarea></label><button type="submit" class="btn primary">Save reply</button></form>`);return;}
