    if(action==='campaign'){open('campaign');return;}if(action==='wheel'){if(current.owner===api.member&&!guestView)wheelBuilder();else pageWheel();return;}if(action==='page-wheel'){pageWheel();return;}if(action==='wheel-wallet'){route('wheel',{wheelTab:'wallet'});return;}
    if(action==='tabs'){show('Manage tabs',`<form data-po-tabs>${['posts','about','photos','videos','live','offers','services','reviews','events'].filter(key=>current.pageType!=='personal'||!['services','reviews'].includes(key)).map(key=>`<label class="po-page-row"><span>${key[0].toUpperCase()+key.slice(1)}</span><input type="checkbox" name="tabs" value="${key}" ${!(current.hiddenTabs||[]).includes(key)?'checked':''} ${key==='posts'?'disabled':''}></label>`).join('')}<button class="btn primary">Save changes</button></form>`);return;}
    if(action==='keywords'){show('Keyword filter',`<form data-po-keywords><label>Keywords<textarea name="keywords" rows="5">${esc((current.poTools?.keywords||[]).join('\n'))}</textarea></label><button class="btn primary">Save changes</button></form>`);return;}
    if(action==='share'||action==='qr'){const url=new URL('/html/v3.1/staff-community.html',location.origin);url.searchParams.set('tab','pages');url.searchParams.set('account','personal');url.searchParams.set('pageId',current.id);url.searchParams.set('pageMode','view');url.searchParams.set('pageTab','posts');if(action==='share'){try{await navigator.clipboard.writeText(url.href);show('Share Page',`<p>Link copied</p><input readonly aria-label="Page link" value="${esc(url.href)}">`);}catch{show('Share Page',`<input readonly aria-label="Page link" value="${esc(url.href)}">`);}}else show('QR + Invite followers',card('Page QR + link',`<p>Scan to open the Page</p><div class="po-page-qr" data-page-qr></div><input readonly aria-label="Page link" value="${esc(url.href)}">${button('Copy link','copy-page',url.href)}<button class="btn soft" data-po-print>Print QR</button><div class="po-page-row"><div><strong>Invite customers to follow</strong><p class="po-page-note">NEXORA ID / phone</p></div>${button('Invite follow','invite-follow')}</div>`)+card('Create a Lucky Wheel on the Page',`<p class="po-page-note">QUICK: select a template · ADVANCED: customize the rules</p><label>Program name<input id="poPageWheelName" value="Follow Page & Spin — win salon gifts"></label><div class="po-page-row"><span>Entry requirements</span><strong>Phone → Follow Page → Spin</strong></div><div class="po-page-row"><span>Wheel</span><strong>6 slots · total probability 100%</strong></div><div class="po-page-row"><span>Prizes</span><strong>Gift card / deal / service</strong></div>${button('Create program','wheel','',true)}`));const qr=document.querySelector('[data-page-qr]');if(qr&&window.QRCode)new window.QRCode(qr,{text:url.href,width:180,height:180});else if(qr)qr.innerHTML='<a href="'+esc(url.href)+'">'+esc(current.title)+'</a>';return;}
